function doPost(e) {
  // Mengizinkan akses dari browser lokal manapun (CORS Fix)
  var headers = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "POST, GET, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type"
  };

  try {
    var data = JSON.parse(e.postData.contents);

    // ID Folder Google Drive "absen guru" Anda
    var folderId = "1-GLl6SUOVH6MSCapdcX1PXzhEyQ_R8m8"; 
    var folder = DriveApp.getFolderById(folderId);

    // Konversi foto Base64 ke File Gambar
    var base64Data = data.foto.replace(/^data:image\/jpeg;base64,/, "").replace(/^data:image\/png;base64,/, "");
    var fotoBlob = Utilities.newBlob(Utilities.base64Decode(base64Data), 'image/jpeg');

    // Penamaan File
    var namaFile = "Absen_" + data.tipe + "_" + data.nama.replace(/\s+/g, '_') + "_" + data.tanggal.replace(/\s+/g, '_') + "_" + data.waktu.replace(/:/g, '-');
    fotoBlob.setName(namaFile + ".jpg");

    // Simpan ke Drive
    folder.createFile(fotoBlob);

    return ContentService.createTextOutput(JSON.stringify({status: "success"}))
                         .setMimeType(ContentService.MimeType.JSON)
                         .setHeaders(headers);

  } catch(error) {
    return ContentService.createTextOutput(JSON.stringify({status: "error", message: error.toString()}))
                         .setMimeType(ContentService.MimeType.JSON)
                         .setHeaders(headers);
  }
}

// WAJIB ADA: Mengizinkan request pengecekan browser (CORS pre-flight)
function doOptions(e) {
  var headers = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "POST, GET, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
    "Access-Control-Max-Age": "86400"
  };
  return ContentService.createTextOutput("").setHeaders(headers);
}

